// Called as the user types in the location box.
export async function searchLocations(
  query: string,
): Promise<LocationSuggestion[]> {
  // TODO: call a geocoding service (Mapbox, Google Places, Nominatim, ...):
  // TODO: const res = await fetch(`${API_BASE}/geocode?q=${encodeURIComponent(query)}`);
  // TODO: return (await res.json()) as LocationSuggestion[];
  await fakeDelay(150);
  const q = query.trim().toLowerCase();
  if (q.length < 2) return [];
  return SAMPLE_PLACES.filter((p) => p.label.toLowerCase().includes(q)).slice(0, 5);
}

